using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Shapes;using ToneCustoms.ShellStudio.Core;
namespace ToneCustoms.ShellStudio.Editor;
public sealed class ViewportControl:Canvas { readonly SceneProjection projection=new();ShellProject? project;public event Action<Guid>? ObjectSelected;public ViewportControl(){Background=new SolidColorBrush(Color.FromRgb(12,12,16));ClipToBounds=true;SizeChanged+=(_,_)=>RenderScene();}public void SetProject(ShellProject p){project=p;RenderScene();}public void RenderScene(){Children.Clear();if(ActualWidth<=0||ActualHeight<=0)return;for(double x=0;x<ActualWidth;x+=35)Children.Add(new Line{X1=x,Y1=0,X2=x,Y2=ActualHeight,Stroke=new SolidColorBrush(Color.FromRgb(30,30,38)),StrokeThickness=1});for(double y=0;y<ActualHeight;y+=35)Children.Add(new Line{X1=0,Y1=y,X2=ActualWidth,Y2=y,Stroke=new SolidColorBrush(Color.FromRgb(30,30,38)),StrokeThickness=1});if(project==null)return;foreach(var p in projection.TopDown(project,35,ActualWidth/2,ActualHeight/2)){var r=new Rectangle{Width=p.Width,Height=p.Height,Fill=new SolidColorBrush(Color.FromArgb(145,94,65,170)),Stroke=new SolidColorBrush(Color.FromRgb(170,145,230)),StrokeThickness=1.5,ToolTip=p.Name,Tag=p.Id};r.MouseLeftButtonDown+=Select;Canvas.SetLeft(r,p.Left);Canvas.SetTop(r,p.Top);Children.Add(r);}}void Select(object s,MouseButtonEventArgs e){if(s is FrameworkElement f&&f.Tag is Guid id){ObjectSelected?.Invoke(id);e.Handled=true;}} }
